class WalletsScreen extends ConsumerWidget { const WalletsScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref){ final wallets=ref.watch(walletsProvider); return Scaffold(appBar: AppBar(title: const Text('المحافظ')), body: ListView.builder(padding: const EdgeInsets.all(16), itemCount: wallets.length, itemBuilder: (_,i){ final w=wallets[i]; return Padding(padding: const EdgeInsets.only(bottom:12), child: NCard(child: Row(children:[Container(width:48,height:48,decoration: BoxDecoration(color: AppColors.primary.withOpacity(0.12), borderRadius: BorderRadius.circular(12)), child: const Icon(Icons.wallet_rounded, color:AppColors.primary)), const SizedBox(width:12), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children:[Text(w.name, style: const TextStyle(fontWeight: FontWeight.w800)), Text(w.type, style: const TextStyle(fontSize:12, color:Colors.grey))])), Text('\${w.balance.toStringAsFixed(2)}', style: const TextStyle(fontWeight: FontWeight.w900, fontSize:18))] ))); }), floatingActionButton: FloatingActionButton(backgroundColor:AppColors.primary, foregroundColor:Colors.white, onPressed: ()=>_add(context, ref), child: const Icon(Icons.add))); } void _add(BuildContext ctx, WidgetRef ref){ final c=TextEditingController(); final b=TextEditingController(text:'0'); showDialog(context: ctx, builder: (_)=> AlertDialog(title: const Text('محفظة جديدة'), content: Column(mainAxisSize:MainAxisSize.min, children:[TextField(controller:c, decoration: const InputDecoration(labelText:'الاسم')), TextField(controller:b, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText:'الرصيد'))]), actions:[TextButton(onPressed: ()=>Navigator.pop(ctx), child: const Text('إلغاء')), ElevatedButton(style: ElevatedButton.styleFrom(backgroundColor:AppColors.primary, foregroundColor:Colors.white), onPressed:(){ final w=WalletModel.create(c.text, double.tryParse(b.text)??0); ref.read(walletsProvider.notifier).add(w); Navigator.pop(ctx);}, child: const Text('إضافة'))])); } }
